//	{ Origin-Realm }
//	[ Destination-Host ]
//	{ Destination-Realm }
//	[ Originating-Request ]
//	[ OC-Supported-Features ]
//	*[ Supported-Features ]
//	{ Public-Identity }
//	[ User-Authorization-Type ]
//	[ Session-Priority ]
//	*[ AVP ]
//	*[ Proxy-Info ]
//	*[ Route-Record ]
