//	{ Vendor-Specific-Application-Id }
//	{ Auth-Session-State }
//	{ Origin-Host }
//	{ Origin-Realm }
//	{ Destination-Realm }
//	{ User-Name }
//	[ Associated-Identities ]
//	*[ Supported-Features ]
//	*[ Public-Identity ]
//	{ Deregistration-Reason }
//	RTR-Flags ]
//	*[ AVP ]
//	*[ Proxy-Info ]
